# More thorough check: for each flagged file, show context around potential mismatches
# by tracking brace/paren depth line by line \(naive - doesn't handle strings perfectly\)

function Check-File {
    param\($FilePath\)

    $lines = Get-Content $FilePath -Encoding UTF8
    $braceDepth = 0
    $parenDepth = 0
    $bracketDepth = 0
    $lineNum = 0
    $braceIssues = @\(\)
    $parenIssues = @\(\)

    foreach \($line in $lines\) {
        $lineNum++
        # Very naive: just count chars per line, track depth
        foreach \($ch in $line.ToCharArray\(\)\) {
            switch \($ch\) {
                '{' { $braceDepth++ }
                '}' { $braceDepth--; if \($braceDepth -lt 0\) { $braceIssues += "Line $lineNum : extra } \(depth went negative\)" } }
                '\(' { $parenDepth++ }
                '\)' { $parenDepth--; if \($parenDepth -lt 0\) { $parenIssues += "Line $lineNum : extra \) \(depth went negative\)" } }
                '[' { $bracketDepth++ }
                ']' { $bracketDepth--; }
            }
        }
    }

    Write-Host "`n=== $\(Split-Path $FilePath -Leaf\) ==="
    Write-Host "Final brace depth: $braceDepth \(should be 0\)"
    Write-Host "Final paren depth: $parenDepth \(should be 0\)"
    Write-Host "Final bracket depth: $bracketDepth \(should be 0\)"
    Write-Host "Total lines: $lineNum"

    if \($braceIssues.Count -gt 0\) {
        Write-Host "Brace issues:"
        $braceIssues | ForEach-Object { Write-Host "  $_" }
    }
    if \($parenIssues.Count -gt 0\) {
        Write-Host "Paren issues:"
        $parenIssues | ForEach-Object { Write-Host "  $_" }
    }
}

