# Strip strings, template literals, and comments before counting braces
function Strip-JSStringsAndComments {
    param\([string]$Content\)

    $result = New-Object System.Text.StringBuilder
    $i = 0
    $len = $Content.Length

    while \($i -lt $len\) {
        $ch = $Content[$i]

        # Single-line comment
        if \($ch -eq '/' -and \($i + 1\) -lt $len -and $Content[$i + 1] -eq '/'\) {
            while \($i -lt $len -and $Content[$i] -ne "`n"\) { $i++ }
            continue
        }

        # Multi-line comment
        if \($ch -eq '/' -and \($i + 1\) -lt $len -and $Content[$i + 1] -eq '*'\) {
            $i += 2
            while \($i -lt \($len - 1\) -and -not \($Content[$i] -eq '*' -and $Content[$i + 1] -eq '/'\)\) { $i++ }
            $i += 2
            continue
        }

        # Template literal
        if \($ch -eq '`'\) {
            $i++
            $depth = 1
            while \($i -lt $len -and $depth -gt 0\) {
                if \($Content[$i] -eq '\\'\) { $i += 2; continue }
                if \($Content[$i] -eq '`'\) { $depth--; $i++; continue }
                # Handle ${...} - we need to track nested template literals
                if \($Content[$i] -eq ' -and \($i + 1\) -lt $len -and $Content[$i + 1] -eq '{'\) {
                    # Inside ${}, braces DO matter for JS syntax, so output them
                    $result.Append\(' '\) | Out-Null
                    $i += 2
                    $braceDepth = 1
                    while \($i -lt $len -and $braceDepth -gt 0\) {
                        if \($Content[$i] -eq '{'\) { $braceDepth++; $result.Append\('{'\) | Out-Null }
                        elseif \($Content[$i] -eq '}'\) { $braceDepth--; if \($braceDepth -gt 0\) { $result.Append\('}'\) | Out-Null } }
                        elseif \($Content[$i] -eq '`'\) {
                            # nested template literal inside ${}
                            $i++
                            while \($i -lt $len -and $Content[$i] -ne '`'\) {
                                if \($Content[$i] -eq '\\'\) { $i++ }
                                $i++
                            }
                            $i++ # skip closing backtick
                            continue
                        }
                        elseif \($Content[$i] -eq "'" -or $Content[$i] -eq '"'\) {
                            $quote = $Content[$i]
                            $i++
                            while \($i -lt $len -and $Content[$i] -ne $quote\) {
                                if \($Content[$i] -eq '\\'\) { $i++ }
                                $i++
                            }
                            $i++ # skip closing quote
                            continue
                        }
                        $i++
                    }
                    continue
                }
                $i++
            }
            continue
        }

        # String literals
        if \($ch -eq "'" -or $ch -eq '"'\) {
            $quote = $ch
            $i++
            while \($i -lt $len -and $Content[$i] -ne $quote\) {
                if \($Content[$i] -eq '\\'\) { $i++ }
                $i++
            }
            $i++ # skip closing quote
            continue
        }

        # Regular character - keep it
        $result.Append\($ch\) | Out-Null
        $i++
    }

    return $result.ToString\(\)
}

function Check-File {
    param\($FilePath\)

    $content = Get-Content $FilePath -Raw -Encoding UTF8
    $stripped = Strip-JSStringsAndComments $content

    $openBrace = \($stripped.ToCharArray\(\) | Where-Object { $_ -eq '{' }\).Count
    $closeBrace = \($stripped.ToCharArray\(\) | Where-Object { $_ -eq '}' }\).Count
    $openParen = \($stripped.ToCharArray\(\) | Where-Object { $_ -eq '\(' }\).Count
    $closeParen = \($stripped.ToCharArray\(\) | Where-Object { $_ -eq '\)' }\).Count
    $openBracket = \($stripped.ToCharArray\(\) | Where-Object { $_ -eq '[' }\).Count
    $closeBracket = \($stripped.ToCharArray\(\) | Where-Object { $_ -eq ']' }\).Count

    $issues = @\(\)
    if \($openBrace -ne $closeBrace\) { $issues += "braces {=$openBrace }=$closeBrace \(diff=$\($openBrace - $closeBrace\)\)" }
    if \($openParen -ne $closeParen\) { $issues += "parens \(=$openParen \)=$closeParen \(diff=$\($openParen - $closeParen\)\)" }
    if \($openBracket -ne $closeBracket\) { $issues += "brackets [=$openBracket ]=$closeBracket \(diff=$\($openBracket - $closeBracket\)\)" }

    $name = Split-Path $FilePath -Leaf
    if \($issues.Count -gt 0\) {
        Write-Host "ISSUE: $name - $\($issues -join ', '\)"
    } else {
        Write-Host "OK: $name"
    }
}

